import{_ as d,C as i,o as t,c as r,a5 as a,b as c,w as s,a as n,E as l,a7 as h}from"./chunks/framework.QWVCgkrI.js";const b=JSON.parse('{"title":"Git stashの内部構造 — 作業ツリーとindexの退避・再適用を追う","description":"","frontmatter":{"title":"Git stashの内部構造 — 作業ツリーとindexの退避・再適用を追う","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"HEAD・index・作業ツリーをつなぐstashのコミット構造から、保存対象、applyとpop、再適用の競合と退避の限界を読む。","aliases":["Git stash","スタッシュ","refs/stash","stash apply","stash pop","作業の退避"],"verification":"Git公式資料と照合し、Windowsの独立リポジトリで親関係・退避対象・再適用と競合を確認（2026-11-18）"}},"headers":[],"relativePath":"tools/git-stash.md","filePath":"tools/git-stash.md"}'),p={name:"tools/git-stash.md"};function m(g,e,u,f,A,x){const o=i("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<h1 id="git-stashの内部構造-—-作業ツリーとindexの退避・再適用を追う" tabindex="-1">Git stashの内部構造 — 作業ツリーとindexの退避・再適用を追う <a class="header-anchor" href="#git-stashの内部構造-—-作業ツリーとindexの退避・再適用を追う" aria-label="Permalink to &quot;Git stashの内部構造 — 作業ツリーとindexの退避・再適用を追う&quot;">​</a></h1><p>敵のHPを20から30にしてステージし、そのあと作業ファイルだけ40に編集しました。別の修正に移るため、途中の状態を <code>git stash push</code> で退避すると、GitはHP30とHP40の両方を保存します。どこまでステージしていたかも、保存される情報の一部です。<a href="https://git-scm.com/docs/git-stash#_description" target="_blank" rel="noreferrer">Git公式のstashマニュアル</a></p><h2 id="この記事で分かること" tabindex="-1">この記事で分かること <a class="header-anchor" href="#この記事で分かること" aria-label="Permalink to &quot;この記事で分かること&quot;">​</a></h2><p>退避に入る内容と、戻したあと一覧に残るかどうかを判断できます。作業ファイルとステージ済みの版がどう保存され、再適用でなぜ競合するのかを説明できます。</p><p><strong>どんなときに使うか</strong>　変更をコミットする前に、別の修正へ一時的に切り替えるときに使います。</p><h2 id="退避する・一覧で確かめる・戻す" tabindex="-1">退避する・一覧で確かめる・戻す <a class="header-anchor" href="#退避する・一覧で確かめる・戻す" aria-label="Permalink to &quot;退避する・一覧で確かめる・戻す&quot;">​</a></h2><p><code>git stash push</code> で追跡ファイルの途中状態を退避します。この例では、index（次のコミットに入れる内容を用意する場所）のHPは30、作業ツリー（手元の編集用ファイル）のHPは40です。通常の <code>stash push</code> 後は、どちらも退避時のHEAD（その時点のコミット）のHP20に戻ります。以下ではこのコミットをHと呼びます。</p><p>一覧で戻したい退避を確かめます。<code>stash@{0}</code> は最新の退避、<code>stash@{1}</code> はその一つ前です。波括弧の数字は、最新を0とする一覧での位置です。</p><p>選んだ退避の変更を、<code>apply</code> または <code>pop</code> で再適用します。<code>apply</code> は適用後も一覧に記録を残します。<code>pop</code> は適用に成功すると、その記録を一覧から外します。別々に初期状態から始めた検証で、applyした2例では記録が残り、成功したpopの例では一覧が空になりました。<a href="https://git-scm.com/docs/git-stash#_commands" target="_blank" rel="noreferrer">Git公式のstashコマンド</a></p><h2 id="applyとpopで何が戻るか" tabindex="-1">applyとpopで何が戻るか <a class="header-anchor" href="#applyとpopで何が戻るか" aria-label="Permalink to &quot;applyとpopで何が戻るか&quot;">​</a></h2><p>Hの状態に退避を再適用すると、HP40を作業ファイルに戻せます。検証したGit 2.39.2では、通常の <code>apply</code> でindexはHP20、作業ツリーはHP40になりました。<code>--index</code> を指定すると、ステージ済みの区切りも戻そうとします。この例のindexはHP30、作業ツリーはHP40になりました。<a href="https://git-scm.com/docs/git-stash#_options" target="_blank" rel="noreferrer">Git公式のstashオプション</a></p><table tabindex="0"><thead><tr><th>Hに再適用した操作</th><th>indexのHP</th><th>作業ツリーのHP</th></tr></thead><tbody><tr><td><code>apply</code></td><td>20</td><td>40</td></tr><tr><td><code>apply --index</code></td><td>30</td><td>40</td></tr><tr><td><code>pop</code></td><td>20</td><td>40</td></tr></tbody></table><p>表は既存の追跡ファイル1つを、この版のGitで確認した結果です。新規ファイルや競合がある場合には条件が異なります。版や設定によってもindexの扱いが変わります。</p><h2 id="未追跡ファイルを含めるかで対象が変わる" tabindex="-1">未追跡ファイルを含めるかで対象が変わる <a class="header-anchor" href="#未追跡ファイルを含めるかで対象が変わる" aria-label="Permalink to &quot;未追跡ファイルを含めるかで対象が変わる&quot;">​</a></h2><p>この例では、Gitがまだ追跡していない <code>notes.txt</code> も置いていました。通常の <code>stash push</code> では退避に含まれず、作業ツリーに残りました。退避のファイル一覧には、追跡していた <code>enemy.txt</code> と <code>stage.txt</code> だけが入りました。<a href="https://git-scm.com/docs/git-stash#_options" target="_blank" rel="noreferrer">Git公式のstashオプション</a></p><p><code>--include-untracked</code>（<code>-u</code>）なら、無視対象以外の未追跡ファイルも保存して作業ツリーから取り除きます。<code>--all</code>（<code>-a</code>）は無視対象のファイルも含める指定です。今回、<code>--all</code> は公式資料で確認しました。<a href="https://git-scm.com/docs/git-stash#_options" target="_blank" rel="noreferrer">Git公式のstashオプション</a></p><h2 id="h・i・wのコミットで二つの途中状態を表す" tabindex="-1">H・I・Wのコミットで二つの途中状態を表す <a class="header-anchor" href="#h・i・wのコミットで二つの途中状態を表す" aria-label="Permalink to &quot;H・I・Wのコミットで二つの途中状態を表す&quot;">​</a></h2><p>通常の <code>git stash push</code> で作った退避をWと呼びます。Wのtree（ファイルの構成を表すデータ）から、追跡ファイルの作業ツリーの状態を読めます。Wの第1親は退避時のHEADであるHです。第2親のIはindexの内容を保存したコミットです。Iの親もHです。この構造から、退避したファイルの内容と、その作業を始めた基準を一緒に読めます。<a href="https://git-scm.com/docs/git-stash#_discussion" target="_blank" rel="noreferrer">Git公式のstashの構造</a> · <a href="/study/tools/git-objects.html">Gitの保存モデル</a></p><p>図の矢印は、参照からコミットへ、またはコミットから親へ向いています。この例の <code>main</code> はHを指し続けます。</p>',19)),(t(),c(h,null,{default:s(()=>[l(o,{id:"mermaid-104",class:"mermaid",graph:"---%0Aconfig%3A%0A%20%20flowchart%3A%0A%20%20%20%20nodeSpacing%3A%2020%0A%20%20%20%20rankSpacing%3A%2032%0A%20%20%20%20padding%3A%208%0A---%0Aflowchart%20TD%0A%20%20%20%20accTitle%3A%20stash%E3%81%8C%E4%BF%9D%E5%AD%98%E3%81%99%E3%82%8B%E4%BD%9C%E6%A5%AD%E3%83%84%E3%83%AA%E3%83%BC%E3%81%A8index%E3%81%AE%E8%A6%AA%E9%96%A2%E4%BF%82%0A%20%20%20%20accDescr%3A%20refs%2Fstash%E3%81%AFW%E3%82%92%E6%8C%87%E3%81%99%E3%80%82W%E3%81%AEtree%E3%81%AFHP40%E3%81%A7%E3%80%81%E7%AC%AC1%E8%A6%AA%E3%81%AFHP20%E3%81%AEH%E3%80%81%E7%AC%AC2%E8%A6%AA%E3%81%AFHP30%E3%81%AEindex%E3%82%92%E4%BF%9D%E5%AD%98%E3%81%97%E3%81%9FI%E3%80%82I%E3%81%AE%E8%A6%AA%E3%81%AFH%E3%80%82%0A%20%20%20%20ref%5B%22refs%2Fstash%22%5D%20--%3E%20w%5B%22W%20%E4%BD%9C%E6%A5%AD%E3%83%84%E3%83%AA%E3%83%BC%20HP40%22%5D%0A%20%20%20%20w%20--%3E%7C%E7%AC%AC2%E8%A6%AA%7C%20idx%5B%22I%20index%20HP30%22%5D%0A%20%20%20%20w%20--%3E%7C%E7%AC%AC1%E8%A6%AA%7C%20head%5B%22H%20%E9%80%80%E9%81%BF%E6%99%82%E3%81%AEHEAD%20HP20%22%5D%0A%20%20%20%20idx%20--%3E%7C%E8%A6%AA%7C%20head%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>最新の退避を指す参照が <code>refs/stash</code> です。reflogは、この参照が以前どこを指していたかの記録です。<code>stash@{1}</code> などの一覧の番号で、reflogから以前の退避をたどれます。図のWの親は、退避した作業の基準Hと、indexを保存したIです。<a href="https://git-scm.com/docs/git-stash#_description" target="_blank" rel="noreferrer">Git公式のstashマニュアル</a> · <a href="/study/tools/git-reflog.html">Gitのreflog</a></p><p><code>stash@{0}^2</code> の <code>^2</code> は、一覧で選んだ最新の退避の第2親を指定します。この例では <code>stash@{0}^1</code> が第1親のH、<code>stash@{0}^2</code> が第2親のIです。</p><p>indexと作業ファイルに別の版が入る例は、ステージングの記事で確認できます。<a href="/study/tools/git-staging-index.html">Gitのステージング</a></p><p>次は独立した検証リポジトリで、stashを作った直後に読んだ結果です。<code>log</code> の出力は先頭がコミットID、そのあとが親のIDです。作業中の <code>main</code> とHのIDはともに <code>08d40dd</code> でした。indexと作業ファイルがHP20に戻ったあとも、元のHP30とHP40は退避から読めます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git log -1 --format=&#39;%h %p&#39; &#39;stash@{0}&#39;</span></span>
<span class="line"><span>85de67c 08d40dd 8d53360</span></span>
<span class="line"><span>$ git log -1 --format=&#39;%h %p&#39; &#39;stash@{0}^2&#39;</span></span>
<span class="line"><span>8d53360 08d40dd</span></span>
<span class="line"><span>$ git show &#39;stash@{0}:enemy.txt&#39;</span></span>
<span class="line"><span>hp=40</span></span>
<span class="line"><span>$ git show &#39;stash@{0}^2:enemy.txt&#39;</span></span>
<span class="line"><span>hp=30</span></span>
<span class="line"><span>$ git show &#39;stash@{0}^1:enemy.txt&#39;</span></span>
<span class="line"><span>hp=20</span></span></code></pre></div><h2 id="再適用する場所が変わると競合する" tabindex="-1">再適用する場所が変わると競合する <a class="header-anchor" href="#再適用する場所が変わると競合する" aria-label="Permalink to &quot;再適用する場所が変わると競合する&quot;">​</a></h2><p>退避後にHPを50にするコミットCを作ったとします。保存した作業はHのHP20からHP40への変更で、いまのCは同じ行をHP50に変えています。Gitは退避の基準H、保存したW、現在の状態を照合して適用します。同じ箇所で二つの値が競合すれば、どちらを使うかを解決する必要があります。<a href="https://git-scm.com/docs/git-stash#_commands" target="_blank" rel="noreferrer">Git公式のstashコマンド</a> · <a href="/study/tools/git-three-way-merge.html">Gitの3-way merge</a></p><p>この検証でCにpopすると、終了コードは1で <code>UU enemy.txt</code> と表示されました。競合したindexの3つの版は、基準のHP20、現在のHP50、退避したHP40でした。HEADはCにとどまり、Wは一覧に残りました。失敗時にも作業ツリーやindexには競合状態や適用できた変更が残り得ます。<code>--index</code> を使う場合も、ステージ済みの状態の復元が競合で失敗することがあります。<a href="https://git-scm.com/docs/git-stash#_commands" target="_blank" rel="noreferrer">Git公式のstashマニュアル</a></p><h2 id="退避の保持とバックアップの範囲" tabindex="-1">退避の保持とバックアップの範囲 <a class="header-anchor" href="#退避の保持とバックアップの範囲" aria-label="Permalink to &quot;退避の保持とバックアップの範囲&quot;">​</a></h2><p>stashは、そのリポジトリ内のコミット、参照、reflogを使って途中状態を記録します。通常のブランチのpushやcloneでstashの一覧まで共有される仕組みではありません。</p><p>通常の <code>stash push</code> に含まれない未追跡ファイルや無視対象ファイルは、保存したつもりでも退避の外に残ります。同じディスク上のリポジトリにだけ退避した場合、そのディスクの故障に対する別のコピーも作られません。また、pop成功やdropで一覧から外れた退避は、ほかの参照でも保持されなければオブジェクトの回収対象になり得ます。退避対象と保存先を確認せずに、プロジェクト全体のバックアップとして扱うことはできません。<a href="https://git-scm.com/docs/git-stash#_commands" target="_blank" rel="noreferrer">Git公式のstashマニュアル</a> · <a href="https://git-scm.com/docs/git-gc#_notes" target="_blank" rel="noreferrer">Git公式のgcマニュアル</a></p><h2 id="補足" tabindex="-1">補足 <a class="header-anchor" href="#補足" aria-label="Permalink to &quot;補足&quot;">​</a></h2><h3 id="gitの版とindexの復元設定" tabindex="-1">Gitの版とindexの復元設定 <a class="header-anchor" href="#gitの版とindexの復元設定" aria-label="Permalink to &quot;Gitの版とindexの復元設定&quot;">​</a></h3><p>表の <code>apply</code> と <code>pop</code> は、<code>stash.index</code> が導入される前のGit 2.39.2で、<code>--index</code> を付けずに実行した結果です。Git 2.52以降で <code>stash.index=true</code> を設定すると、<code>--index</code> を省略したapplyやpopでもindexの復元を試みます。この設定の既定値は <code>false</code> です。<a href="https://git-scm.com/docs/git-stash/2.52.0#_configuration" target="_blank" rel="noreferrer">Git 2.52のstash設定</a></p><h3 id="未追跡ファイルを保存したコミット" tabindex="-1">未追跡ファイルを保存したコミット <a class="header-anchor" href="#未追跡ファイルを保存したコミット" aria-label="Permalink to &quot;未追跡ファイルを保存したコミット&quot;">​</a></h3><p><code>--include-untracked</code> を使った別の検証ではWに第3親ができ、そのコミットのtreeから <code>notes.txt</code> を読めました。</p><h3 id="退避の書き出しと読み込み" tabindex="-1">退避の書き出しと読み込み <a class="header-anchor" href="#退避の書き出しと読み込み" aria-label="Permalink to &quot;退避の書き出しと読み込み&quot;">​</a></h3><p>Git 2.51以降には明示的な <code>export</code> と <code>import</code> もありますが、今回の検証対象には含めていません。<a href="https://git-scm.com/docs/git-stash#_commands" target="_blank" rel="noreferrer">Git公式のstashマニュアル</a></p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ul><li>通常の <code>stash push</code> は、追跡ファイルの作業ツリーとindexの状態を保存します。未追跡ファイルを含めるには指定が必要です。</li><li><code>stash@{0}</code> は最新の退避です。<code>^2</code> を付けると、その退避の第2親に保存したindexを指します。</li><li><code>apply</code> は一覧に記録を残し、<code>pop</code> は適用に成功すると一覧から外します。再適用が競合したときは、記録が残っても作業ツリーやindexの確認が必要です。</li><li>退避に入るファイルと保存先には範囲があります。通常のpushやcloneで退避は共有されません。</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>退避時、indexがHP30、作業ファイルがHP40なら、どちらが保存される？</summary><p>両方です。Wのtreeは作業ファイルのHP40を持ち、Wの第2親IのtreeはindexのHP30を持ちます。</p></details><details class="details custom-block"><summary>popで競合したらstashの一覧からも消える？</summary><p>この競合では記録が残ります。今回もWは一覧に残り、作業ツリーとindexは競合した状態になりました。</p></details><details class="details custom-block"><summary>通常のstash pushで未追跡のメモも退避される？</summary><p>通常は含まれません。今回の <code>notes.txt</code> は作業ツリーに残りました。未追跡ファイルを含める <code>--include-untracked</code> では別のコミットに保存されました。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月18日に、WindowsのGit 2.39.2.windows.1と独立したSHA-1リポジトリ6つを使いました。HP20をコミットし、HP30をステージしてHP40に再編集した状態から、通常の <code>stash push</code>、apply、applyの <code>--index</code>、成功するpop、HP50に変えたあとの競合するpop、<code>--include-untracked</code> の保存を、それぞれ使い捨て環境で確認しました。本文の既定のapplyは、この版と条件での観察です。<code>stash.index</code>、export/import、<code>--all</code>、<code>--keep-index</code>、部分退避、サブモジュール、複数ファイルの競合、オブジェクトの回収時期は実測していません。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/tools/git-staging-index.html">Gitのステージング</a> — ステージ済みと未ステージの版を分けて読む。</li><li><a href="/study/tools/git-restore.html">Git restoreの仕組み</a> — 保存元の版からindex・作業ツリーへ写す操作を確認する。</li><li><a href="/study/tools/git-reflog.html">Gitのreflog</a> — 参照の更新記録とオブジェクトの保持の関係を読む。</li><li><a href="/study/tools/git-objects.html">Gitの保存モデル</a> · <a href="/study/tools/git-three-way-merge.html">Gitの3-way merge</a> — tree・親関係と、異なる変更を照合する仕組みを確認する。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/git-stash" target="_blank" rel="noreferrer">Git公式 — git-stash</a></li><li><a href="https://git-scm.com/docs/gitrevisions" target="_blank" rel="noreferrer">Git公式 — gitrevisions</a></li><li><a href="https://git-scm.com/docs/git-gc#_notes" target="_blank" rel="noreferrer">Git公式 — git-gc</a></li><li><a href="https://git-scm.com/docs/git-stash/2.52.0#_configuration" target="_blank" rel="noreferrer">Git 2.52 — stash.index設定</a></li></ul>`,30))])}const _=d(p,[["render",m]]);export{b as __pageData,_ as default};
